export default function RouteNotice() {
  const pathname = usePathname() || '/';
  const key = pathname !== '/' && pathname.endsWith('/') ? pathname.slice(0, -1) : pathname;
  const reason = NOTICES[key];
  if (reason === undefined) return null;

  return (
    <div className="bg-slate-900 px-4 pt-4">
      <div className="mx-auto max-w-[1600px]">
        <HallucinationBanner reason={reason || undefined} />
      </div>
    </div>
  );
}
